void E2ETests::completeUserJourney(){QTemporaryDir dir;const QString path=dir.filePath(QStringLiteral("settings.ini"));auto fake=std::make_unique<FakePlatform>();FakePlatform *raw=fake.get();ApplicationController controller(std::move(fake),SettingsStore(path));controller.initialize();QSignalSpy operationStarted(&controller,&ApplicationController::operationStarted);QSignalSpy operationFinished(&controller,&ApplicationController::operationFinished);MainPanel panel(&controller);panel.show();QTest::qWait(50);
    auto *version=panel.findChild<QLabel*>(QStringLiteral("header-version"));QVERIFY(version);QCOMPARE(version->text(),QStringLiteral("v1.2 Windows"));
    QCheckBox *eink=nullptr;for(QCheckBox *candidate:panel.findChildren<QCheckBox*>(QStringLiteral("eink-checkbox")))if(candidate->property("displayId").toString()==QStringLiteral("fake-external"))eink=candidate;QVERIFY(eink);eink->click();QTRY_VERIFY(controller.settingsFor(QStringLiteral("fake-external")).isEink);QVERIFY(raw->effectsReduced);QCoreApplication::processEvents();
    auto *visualEffects=panel.findChild<QAbstractButton*>(QStringLiteral("visual-effects-switch"));auto *follow=panel.findChild<QAbstractButton*>(QStringLiteral("auto-visual-effects-switch"));auto *followLabel=panel.findChild<QLabel*>(QStringLiteral("auto-visual-effects-label"));auto *night=panel.findChild<QAbstractButton*>(QStringLiteral("disable-night-light-switch"));auto *nightNote=panel.findChild<QLabel*>(QStringLiteral("disable-night-light-note"));auto *lightMode=panel.findChild<QAbstractButton*>(QStringLiteral("windows-light-mode-switch"));auto *lightNote=panel.findChild<QLabel*>(QStringLiteral("windows-light-mode-note"));QVERIFY(visualEffects);QVERIFY(follow);QVERIFY(followLabel);QVERIFY(night);QVERIFY(nightNote);QVERIFY(lightMode);QVERIFY(lightNote);QVERIFY(!followLabel->wordWrap());QVERIFY(!nightNote->wordWrap());QVERIFY(!lightNote->wordWrap());QCOMPARE(nightNote->text(),QStringLiteral("⚠ ")+L("night.disable.note"));QCOMPARE(lightNote->text(),L("system.lightMode.note"));QVERIFY(!night->isChecked());QVERIFY(follow->y()>visualEffects->y());QVERIFY(night->mapTo(&panel,QPoint()).y()>follow->mapTo(&panel,QPoint()).y());QVERIFY(lightMode->mapTo(&panel,QPoint()).y()>night->mapTo(&panel,QPoint()).y());night->click();QTRY_VERIFY(raw->nightDisabled);QTRY_VERIFY(!night->isHidden());QCOMPARE(raw->nightDisableCalls,1);night->click();QTRY_VERIFY(!raw->nightDisabled);QTRY_VERIFY(!night->isHidden());QVERIFY(raw->nightLightEnabled());QEvent deactivated(QEvent::WindowDeactivate);QApplication::sendEvent(&panel,&deactivated);QTRY_VERIFY(!panel.isVisible());QVERIFY(raw->nightLightEnabled());panel.show();night=panel.findChild<QAbstractButton*>(QStringLiteral("disable-night-light-switch"));QVERIFY(night);night->click();QTRY_VERIFY(raw->nightDisabled);QTRY_VERIFY(!night->isHidden());lightMode=panel.findChild<QAbstractButton*>(QStringLiteral("windows-light-mode-switch"));QVERIFY(lightMode);lightMode->click();QTRY_VERIFY(raw->lightMode);QCOMPARE(raw->lightModeCalls,1);
    QVERIFY(!panel.findChild<QAbstractButton*>(QStringLiteral("shaking-switch")));
    QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("night-light-button")));
    auto *anime=panel.findChild<QPushButton*>(QStringLiteral("preset-anime"));QVERIFY(anime&&anime->isEnabled());anime->click();QCOMPARE(controller.settingsFor(QStringLiteral("fake-external")).saturation,2.0);QCOMPARE(panel.findChild<QSlider*>(QStringLiteral("saturation-slider"))->value(),200);QTRY_VERIFY(raw->colorApplyCalls>0);
    auto *rgbToggle=panel.findChild<QPushButton*>(QStringLiteral("rgb-toggle"));QVERIFY(rgbToggle);rgbToggle->click();QCoreApplication::processEvents();auto *red=panel.findChild<QSlider*>(QStringLiteral("rgb-red"));auto *rgbReset=panel.findChild<QPushButton*>(QStringLiteral("rgb-reset"));QVERIFY(red);QVERIFY(rgbReset);red->setValue(120);QVERIFY(rgbReset->isEnabled());QMetaObject::invokeMethod(red,"sliderReleased",Qt::DirectConnection);QCoreApplication::processEvents();QCOMPARE(controller.settingsFor(QStringLiteral("fake-external")).rgb.red,1.2);rgbReset->click();QVERIFY(controller.settingsFor(QStringLiteral("fake-external")).rgb.isIdentity());QCOMPARE(panel.findChild<QSlider*>(QStringLiteral("rgb-red"))->value(),100);QCOMPARE(panel.findChild<QSlider*>(QStringLiteral("rgb-green"))->value(),100);QCOMPARE(panel.findChild<QSlider*>(QStringLiteral("rgb-blue"))->value(),100);QVERIFY(!rgbReset->isEnabled());
    QVERIFY(panel.findChild<QLabel*>(QStringLiteral("text-caption")));QVERIFY(panel.findChild<QLabel*>(QStringLiteral("video-caption")));auto *solid=panel.findChild<QPushButton*>(QStringLiteral("text-solid"));QVERIFY(solid);solid->click();QCOMPARE(controller.settingsFor(QStringLiteral("fake-external")).textLevel,TextLevel::Solid);QCoreApplication::processEvents();auto *detail=panel.findChild<QLabel*>(QStringLiteral("text-detail"));auto *blocked=panel.findChild<QLabel*>(QStringLiteral("video-blocked"));QVERIFY(detail);QVERIFY(blocked);QCOMPARE(detail->text(),L("text.detail.solid"));QCOMPARE(blocked->text(),L("video.blocked"));auto *helperArea=panel.findChild<QScrollArea*>();QVERIFY(helperArea);helperArea->ensureWidgetVisible(blocked,20,20);QCoreApplication::processEvents();QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-text-helper.png")));
    auto *medium=panel.findChild<QPushButton*>(QStringLiteral("video-medium"));QVERIFY(medium);medium->click();QCOMPARE(controller.settingsFor(QStringLiteral("fake-external")).enhanceLevel,EnhanceLevel::Medium);QCOMPARE(controller.settingsFor(QStringLiteral("fake-external")).textLevel,TextLevel::Off);QCoreApplication::processEvents();auto *warning=panel.findChild<QLabel*>(QStringLiteral("video-warning"));QVERIFY(warning);QVERIFY(warning->text().contains(L("cost.34")));helperArea->ensureWidgetVisible(warning,20,20);QCoreApplication::processEvents();QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-video-warning.png")));
    auto *advanced=panel.findChild<QAbstractButton*>(QStringLiteral("advanced-switch"));QVERIFY(advanced);advanced->click();QTRY_VERIFY(controller.settingsFor(QStringLiteral("fake-external")).advanced);QCoreApplication::processEvents();auto *gamma=panel.findChild<QSlider*>(QStringLiteral("curve-gamma"));QVERIFY(gamma);gamma->setValue(214);QMetaObject::invokeMethod(gamma,"sliderReleased",Qt::DirectConnection);QCOMPARE(controller.settingsFor(QStringLiteral("fake-external")).customCurve.gamma,2.14);
    QCoreApplication::processEvents();auto *slot=panel.findChild<QPushButton*>(QStringLiteral("curve-slot-1"));QVERIFY(slot);slot->click();QVERIFY(controller.settings().savedCurves[0].occupied);
    QCoreApplication::processEvents();auto *login=panel.findChild<QAbstractButton*>(QStringLiteral("launch-login-switch"));QVERIFY(login);login->click();QVERIFY(controller.settings().launchAtLogin);QVERIFY(raw->login);
    controller.waitForPendingOperations();QCoreApplication::processEvents();QVERIFY(operationStarted.count()>0);QCOMPARE(operationStarted.count(),operationFinished.count());QDir().mkpath(QStringLiteral("artifacts"));panel.grab().save(QStringLiteral("artifacts/e2e-main.png"));controller.shutdown();QVERIFY(raw->shutDown);QVERIFY(!raw->nightDisabled);QVERIFY(!raw->lightMode);QCOMPARE(raw->lightModeCalls,2);SettingsStore reload(path);AppSettings saved=reload.load();QVERIFY(saved.forDisplay(QStringLiteral("fake-external")).advanced);QCOMPARE(saved.forDisplay(QStringLiteral("fake-external")).saturation,2.0);}

void E2ETests::windows7CapabilityPath(){QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>(false,false);fake->displayList[0].colorAdjustmentUpgradeMayHelp=true;ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("s.ini"))));controller.initialize();MainPanel panel(&controller);panel.show();QCheckBox *eink=nullptr;for(QCheckBox *candidate:panel.findChildren<QCheckBox*>(QStringLiteral("eink-checkbox")))if(candidate->property("displayId").toString()==QStringLiteral("fake-external"))eink=candidate;QVERIFY(eink);eink->click();QCoreApplication::processEvents();QVERIFY(!panel.findChild<QSlider*>(QStringLiteral("saturation-slider")));QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("rgb-toggle")));QVERIFY(panel.findChild<QWidget*>(QStringLiteral("saturation-unsupported")));QCOMPARE(panel.findChild<QLabel*>(QStringLiteral("saturation-unsupported-note"))->text(),L("saturation.unsupported.upgrade"));QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("gpu-control-panel-button")));QVERIFY(!panel.findChild<QAbstractButton*>(QStringLiteral("windows-light-mode-switch")));QVERIFY(!panel.findChild<QAbstractButton*>(QStringLiteral("disable-night-light-switch")));QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("night-light-button")));QVERIFY(!panel.findChild<QLabel*>(QStringLiteral("night-light-fallback-recommendation")));QVERIFY(!panel.findChild<QLabel*>(QStringLiteral("night-light-settings-path")));QVERIFY(!panel.findChild<QAbstractButton*>(QStringLiteral("shaking-switch")));auto *text=panel.findChild<QPushButton*>(QStringLiteral("text-medium"));QVERIFY(text&&text->isEnabled());QWidget *card=eink;while(card&&card->objectName()!=QStringLiteral("displayCard"))card=card->parentWidget();QVERIFY(card);QTRY_VERIFY(card->height()>300);text->click();QCOMPARE(controller.settingsFor(QStringLiteral("fake-external")).textLevel,TextLevel::Medium);QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-windows7-gated.png")));controller.shutdown();}

void E2ETests::windows10CompatibilityColorPath(){
    QTemporaryDir dir;const QString settingsPath=dir.filePath(QStringLiteral("windows10.ini"));AppSettings initial;initial.language=QStringLiteral("zh-Hans");SettingsStore(settingsPath).save(initial);
    auto fake=std::make_unique<FakePlatform>();FakePlatform *raw=fake.get();auto &display=raw->displayList[0];display.acmSupported=false;display.acmEnabled=false;display.colorAdjustmentSupported=true;display.usesWindows10Mhc2=true;display.colorCapabilityFingerprint=QStringLiteral("win10-test-fingerprint");display.graphicsVendor=GraphicsVendor::Amd;display.graphicsAdapterName=QStringLiteral("AMD Radeon 780M Graphics");display.gpuControlPanelAvailable=true;
    ApplicationController controller(std::move(fake),SettingsStore(settingsPath));controller.setColorSafetyTickIntervalForTests(100);controller.initialize();controller.setEink(QStringLiteral("fake-external"),true);controller.waitForPendingOperations();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();
    QVERIFY(!panel.findChild<QSlider*>(QStringLiteral("saturation-slider")));QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("rgb-toggle")));QVERIFY(panel.findChild<QAbstractButton*>(QStringLiteral("experimental-color-switch")));QCOMPARE(panel.findChild<QLabel*>(QStringLiteral("saturation-unsupported-note"))->text(),L("saturation.manual"));QVERIFY(panel.findChild<QPushButton*>(QStringLiteral("gpu-control-panel-button")));QCOMPARE(raw->colorApplyCalls,0);QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-windows10-experimental-off.png")));
    panel.findChild<QAbstractButton*>(QStringLiteral("experimental-color-switch"))->click();QCoreApplication::processEvents();QCOMPARE(controller.colorSafetyPhase(QStringLiteral("fake-external")),ColorSafetyPhase::Preparing);auto *overlay=panel.findChild<QWidget*>(QStringLiteral("color-safety-overlay"));auto *dialog=panel.findChild<QWidget*>(QStringLiteral("color-safety-dialog"));auto *actions=panel.findChild<QWidget*>(QStringLiteral("color-safety-actions"));QVERIFY(overlay&&overlay->isVisible());QCOMPARE(overlay->geometry(),panel.rect());QVERIFY(dialog&&dialog->isVisible());QVERIFY(qAbs(dialog->geometry().center().x()-panel.rect().center().x())<=2);QVERIFY(qAbs(dialog->geometry().center().y()-panel.rect().center().y())<=2);QVERIFY(panel.findChild<QLabel*>(QStringLiteral("color-safety-countdown"))->isVisible());QVERIFY(actions&&!actions->isVisible());QTest::qWait(20);QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-windows10-experimental-preparing.png")));
    QTRY_COMPARE(controller.colorSafetyPhase(QStringLiteral("fake-external")),ColorSafetyPhase::AwaitingConfirmation);auto *rollback=panel.findChild<QPushButton*>(QStringLiteral("color-safety-rollback"));auto *confirm=panel.findChild<QPushButton*>(QStringLiteral("color-safety-confirm"));auto *countdown=panel.findChild<QLabel*>(QStringLiteral("color-safety-countdown"));QVERIFY(panel.isVisible());QVERIFY(actions->isVisible());QVERIFY(rollback&&rollback->isVisible());QVERIFY(rollback->isEnabled());QVERIFY(confirm&&confirm->isVisible());QVERIFY(confirm->isEnabled());QCOMPARE(confirm->height(),rollback->height());QVERIFY(countdown&&countdown->font().pointSize()>=32);QVERIFY(confirm->text().contains(QStringLiteral("显示正常")));QVERIFY(confirm->font().weight()>=QFont::Bold);QVERIFY(confirm->styleSheet().contains(QStringLiteral("#c62828")));QCOMPARE(raw->colorSafetyBeginCalls,1);QTest::qWait(20);QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-windows10-experimental-confirm.png")));
    rollback->click();QTRY_COMPARE(controller.colorSafetyPhase(QStringLiteral("fake-external")),ColorSafetyPhase::Idle);QVERIFY(!controller.colorExperimentDenied(QStringLiteral("fake-external")));QVERIFY(controller.colorExperimentAvailable(QStringLiteral("fake-external")));QTRY_VERIFY(panel.findChild<QPushButton*>(QStringLiteral("gpu-control-panel-button"))->isVisible());
    QAbstractButton *retrySwitch=nullptr;QTRY_VERIFY(([&]{retrySwitch=nullptr;for(auto *candidate:panel.findChildren<QAbstractButton*>(QStringLiteral("experimental-color-switch")))if(candidate->isVisible()&&candidate->property("displayId").toString()==QStringLiteral("fake-external")){retrySwitch=candidate;break;}return retrySwitch&&retrySwitch->isEnabled();})());QVERIFY(!retrySwitch->isChecked());retrySwitch->click();QCOMPARE(controller.colorSafetyPhase(QStringLiteral("fake-external")),ColorSafetyPhase::Preparing);QTRY_COMPARE(controller.colorSafetyPhase(QStringLiteral("fake-external")),ColorSafetyPhase::AwaitingConfirmation);QVERIFY(panel.findChild<QPushButton*>(QStringLiteral("color-safety-confirm"))->isVisible());panel.findChild<QPushButton*>(QStringLiteral("color-safety-confirm"))->click();QTRY_VERIFY(panel.findChild<QSlider*>(QStringLiteral("saturation-slider")));QVERIFY(panel.findChild<QPushButton*>(QStringLiteral("rgb-toggle")));QVERIFY(!panel.findChild<QWidget*>(QStringLiteral("saturation-unsupported")));QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("gpu-control-panel-button")));controller.waitForPendingOperations();QVERIFY(raw->colorApplyCalls>0);QVERIFY(controller.settingsFor(QStringLiteral("fake-external")).experimentalColorEnabled);QTest::qWait(20);QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-windows10-experimental-color.png")));controller.shutdown();Localization::instance().setLanguage(QStringLiteral("en"));
}

void E2ETests::cloneModeWarningAndSingleOwner(){
    QTemporaryDir dir;AppSettings initial;initial.language=QStringLiteral("zh-Hans");initial.forDisplay(QStringLiteral("fake-external")).isEink=true;const QString path=dir.filePath(QStringLiteral("clone-ui.ini"));SettingsStore(path).save(initial);
    auto fake=std::make_unique<FakePlatform>();DisplayInfo &external=fake->displayList[0];DisplayInfo &builtIn=fake->displayList[1];builtIn.friendlyName=QStringLiteral("Internal Display");builtIn.friendlyNameIsFallback=true;external.cloneMode=true;external.cloneGroupKey=QStringLiteral("adapter:source-0");external.clonePeerNames=QStringList{builtIn.friendlyName};external.cloneTargetIds={1,2};builtIn.cloneMode=true;builtIn.cloneGroupKey=external.cloneGroupKey;builtIn.clonePeerNames=QStringList{external.friendlyName};builtIn.cloneTargetIds={1,2};
    ApplicationController controller(std::move(fake),SettingsStore(path));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();auto *warning=panel.findChild<QLabel*>(QStringLiteral("clone-mode-warning"));QVERIFY(warning&&warning->isVisible());QVERIFY(warning->text().contains(QStringLiteral("复制模式")));QVERIFY(warning->text().contains(L("display.internal")));QVERIFY(!warning->styleSheet().contains(QStringLiteral("700")));QVERIFY(!controller.colorControlsEnabled(external.stableId));QVERIFY(!panel.findChild<QSlider*>(QStringLiteral("saturation-slider")));QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("rgb-toggle")));QVERIFY(!panel.findChild<QAbstractButton*>(QStringLiteral("experimental-color-switch")));QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("gpu-control-panel-button")));auto *unsupported=panel.findChild<QLabel*>(QStringLiteral("saturation-unsupported-note"));QVERIFY(unsupported);QCOMPARE(unsupported->text(),L("saturation.unsupported.clone"));QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-clone-mode-warning.png")));
    QCheckBox *builtInBox=nullptr;for(QCheckBox *candidate:panel.findChildren<QCheckBox*>(QStringLiteral("eink-checkbox")))if(candidate->property("displayId").toString()==builtIn.stableId)builtInBox=candidate;QVERIFY(builtInBox);builtInBox->click();QTRY_VERIFY(controller.settingsFor(builtIn.stableId).isEink);QTRY_VERIFY(!controller.settingsFor(external.stableId).isEink);controller.waitForPendingOperations();controller.shutdown();Localization::instance().setLanguage(QStringLiteral("en"));
}

void E2ETests::unsupportedSaturationOffersMatchingGpuPanel(){
    QTemporaryDir dir;
    auto fake=std::make_unique<FakePlatform>(false);FakePlatform *raw=fake.get();
    DisplayInfo &display=raw->displayList[0];display.colorAdjustmentUpgradeMayHelp=true;display.graphicsVendor=GraphicsVendor::Amd;display.graphicsAdapterName=QStringLiteral("AMD Radeon 780M Graphics");display.gpuControlPanelAvailable=true;
    ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("unsupported-upgrade.ini"))));controller.initialize();controller.setEink(display.stableId,true);controller.waitForPendingOperations();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();
    QVERIFY(!panel.findChild<QSlider*>(QStringLiteral("saturation-slider")));QVERIFY(!panel.findChild<QPushButton*>(QStringLiteral("rgb-toggle")));
    auto *note=panel.findChild<QLabel*>(QStringLiteral("saturation-unsupported-note"));auto *gpu=panel.findChild<QLabel*>(QStringLiteral("saturation-gpu-name"));auto *open=panel.findChild<QPushButton*>(QStringLiteral("gpu-control-panel-button"));
    QVERIFY(note);QCOMPARE(note->text(),L("saturation.unsupported.upgrade"));QVERIFY(gpu);QVERIFY(gpu->text().contains(QStringLiteral("AMD Radeon 780M Graphics")));QVERIFY(open);QCOMPARE(open->text(),L("saturation.open.amd"));QCOMPARE(open->property("graphicsVendor").toInt(),static_cast<int>(GraphicsVendor::Amd));QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-unsupported-saturation.png")));open->click();QCOMPARE(raw->gpuPanelOpenCalls,1);QCOMPARE(raw->lastGpuPanelDisplayId,QStringLiteral("fake-external"));controller.shutdown();

    auto currentFake=std::make_unique<FakePlatform>(false);currentFake->displayList[0].colorAdjustmentUpgradeMayHelp=false;currentFake->displayList[0].graphicsVendor=GraphicsVendor::Nvidia;currentFake->displayList[0].graphicsAdapterName=QStringLiteral("NVIDIA GeForce GTX 1060");currentFake->displayList[0].gpuControlPanelAvailable=true;
    ApplicationController currentController(std::move(currentFake),SettingsStore(dir.filePath(QStringLiteral("unsupported-current.ini"))));currentController.initialize();currentController.setEink(QStringLiteral("fake-external"),true);currentController.waitForPendingOperations();MainPanel currentPanel(&currentController);currentPanel.show();QCoreApplication::processEvents();
    QCOMPARE(currentPanel.findChild<QLabel*>(QStringLiteral("saturation-unsupported-note"))->text(),L("saturation.unsupported.driver"));QCOMPARE(currentPanel.findChild<QPushButton*>(QStringLiteral("gpu-control-panel-button"))->text(),L("saturation.open.nvidia"));QVERIFY(!currentPanel.findChild<QLabel*>(QStringLiteral("saturation-unsupported-note"))->text().contains(QStringLiteral("may add support")));currentController.shutdown();

    auto intelFake=std::make_unique<FakePlatform>(false);intelFake->displayList[0].graphicsVendor=GraphicsVendor::Intel;intelFake->displayList[0].graphicsAdapterName=QStringLiteral("Intel UHD Graphics 620");intelFake->displayList[0].gpuControlPanelAvailable=true;
    ApplicationController intelController(std::move(intelFake),SettingsStore(dir.filePath(QStringLiteral("unsupported-intel.ini"))));intelController.initialize();intelController.setEink(QStringLiteral("fake-external"),true);intelController.waitForPendingOperations();MainPanel intelPanel(&intelController);intelPanel.show();QCoreApplication::processEvents();
    QCOMPARE(intelPanel.findChild<QPushButton*>(QStringLiteral("gpu-control-panel-button"))->text(),L("saturation.open.intel"));intelController.shutdown();
}

