void E2ETests::nightLightSwitchSynchronizesWithSystem(){QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();FakePlatform *raw=fake.get();raw->nightDisabled=true;ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("sync.ini"))));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();auto *toggle=panel.findChild<QAbstractButton*>(QStringLiteral("disable-night-light-switch"));auto *status=panel.findChild<QLabel*>(QStringLiteral("disable-night-light-status"));auto *note=panel.findChild<QLabel*>(QStringLiteral("disable-night-light-note"));QVERIFY(toggle);QVERIFY(status);QVERIFY(note);QVERIFY(toggle->isChecked());QCOMPARE(status->text(),L("system.on"));QCOMPARE(note->text(),QStringLiteral("⚠ ")+L("night.disable.note"));QVERIFY(!note->wordWrap());QVERIFY(!note->isVisible());QVERIFY(!panel.findChild<QLabel*>(QStringLiteral("night-light-warning")));raw->nightDisabled=false;controller.refreshNightLightState();QCoreApplication::processEvents();QVERIFY(!toggle->isChecked());QCOMPARE(status->text(),L("system.off"));QVERIFY(note->isVisible());QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-night-light-warning.png")));raw->nightDisabled=true;controller.refreshNightLightState();QCoreApplication::processEvents();QVERIFY(toggle->isChecked());QCOMPARE(status->text(),L("system.on"));QVERIFY(!note->isVisible());controller.shutdown();}

