void E2ETests::cjkLanguagesUseWindowsUiFonts(){
    if(QGuiApplication::platformName()==QStringLiteral("offscreen"))QSKIP("The offscreen Qt plugin does not enumerate Windows system fonts.");
    QString baseStyle=QApplication::style()->objectName();if(baseStyle.isEmpty())baseStyle=QStringLiteral("windowsvista");QApplication::setStyle(new ui::SmoothProxyStyle(baseStyle));
    Localization::instance().setLanguage(QStringLiteral("zh-Hans"));QVERIFY(QApplication::font().family()==QStringLiteral("Microsoft YaHei UI")||QApplication::font().family()==QStringLiteral("Microsoft YaHei"));QCOMPARE(QFontInfo(QApplication::font()).family(),QApplication::font().family());
    Localization::instance().setLanguage(QStringLiteral("zh-Hant"));QVERIFY(QApplication::font().family()==QStringLiteral("Microsoft JhengHei UI")||QApplication::font().family()==QStringLiteral("Microsoft JhengHei"));QCOMPARE(QFontInfo(QApplication::font()).family(),QApplication::font().family());
    Localization::instance().setLanguage(QStringLiteral("ja"));QVERIFY(QApplication::font().family()==QStringLiteral("Yu Gothic UI")||QApplication::font().family()==QStringLiteral("Meiryo UI")||QApplication::font().family()==QStringLiteral("Meiryo"));QCOMPARE(QFontInfo(QApplication::font()).family(),QApplication::font().family());
    QVERIFY((QApplication::font().styleStrategy()&QFont::PreferAntialias)!=0);QCOMPARE(QApplication::font().hintingPreference(),QFont::PreferNoHinting);
    Localization::instance().setLanguage(QStringLiteral("en"));QCOMPARE(QApplication::font().family(),QStringLiteral("Segoe UI"));QCOMPARE(QFontInfo(QApplication::font()).family(),QApplication::font().family());
    auto capture=[](const QString &language,const QString &fileName){QTemporaryDir dir;const QString path=dir.filePath(QStringLiteral("language.ini"));AppSettings settings;settings.language=language;SettingsStore(path).save(settings);auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(path));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();QDir().mkpath(QStringLiteral("artifacts"));const bool saved=panel.grab().save(QStringLiteral("artifacts/")+fileName);controller.shutdown();return saved;};
    QVERIFY(capture(QStringLiteral("zh-Hans"),QStringLiteral("e2e-cjk.png")));QVERIFY(capture(QStringLiteral("zh-Hant"),QStringLiteral("e2e-zh-Hant.png")));QVERIFY(capture(QStringLiteral("ja"),QStringLiteral("e2e-ja.png")));
    Localization::instance().setLanguage(QStringLiteral("en"));
}

