    const QImage indicatorImage=indicator->grab().toImage().convertToFormat(QImage::Format_ARGB32);const QPoint clearSample=spinner->mapTo(indicator,QPoint(1,1));const QColor clearColor=indicatorImage.pixelColor(clearSample);QVERIFY2(clearColor.red()>=235&&clearColor.red()<252&&clearColor.red()==clearColor.green()&&clearColor.green()==clearColor.blue(),qPrintable(QStringLiteral("Spinner corner was not transparent over the processing pill: %1").arg(clearColor.name())));
