void E2ETests::slowSystemTogglesUseLocalSpinner(){
    QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();FakePlatform *raw=fake.get();raw->systemDelayMs=350;ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("slow-system.ini"))));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();
    auto *visual=panel.findChild<QAbstractButton*>(QStringLiteral("visual-effects-switch"));auto *visualSpinner=panel.findChild<QWidget*>(QStringLiteral("visual-effects-spinner"));auto *visualStatus=panel.findChild<QLabel*>(QStringLiteral("visual-effects-status"));auto *night=panel.findChild<QAbstractButton*>(QStringLiteral("disable-night-light-switch"));auto *nightSpinner=panel.findChild<QWidget*>(QStringLiteral("disable-night-light-spinner"));auto *nightStatus=panel.findChild<QLabel*>(QStringLiteral("disable-night-light-status"));auto *light=panel.findChild<QAbstractButton*>(QStringLiteral("windows-light-mode-switch"));auto *lightSpinner=panel.findChild<QWidget*>(QStringLiteral("windows-light-mode-spinner"));auto *lightStatus=panel.findChild<QLabel*>(QStringLiteral("windows-light-mode-status"));auto *headerBusy=panel.findChild<QWidget*>(QStringLiteral("inline-processing"));
    QVERIFY(visual);QVERIFY(visualSpinner);QVERIFY(visualStatus);QVERIFY(night);QVERIFY(nightSpinner);QVERIFY(nightStatus);QVERIFY(light);QVERIFY(lightSpinner);QVERIFY(lightStatus);QVERIFY(headerBusy);QElapsedTimer timer;
    timer.start();visual->click();QCoreApplication::processEvents();QVERIFY2(timer.elapsed()<100,"Visual-effects click blocked the GUI thread.");QVERIFY(!visual->isVisible());QVERIFY(visualSpinner->isVisible());QVERIFY(!headerBusy->isVisible());QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-local-system-spinner-active.png")));QTest::qWait(300);QVERIFY(!headerBusy->isVisible());QTRY_VERIFY_WITH_TIMEOUT(visual->isVisible(),1000);QVERIFY(!visualSpinner->isVisible());QVERIFY(raw->effectsReduced);QCOMPARE(visualStatus->text(),L("system.on"));
    timer.restart();night->click();QCoreApplication::processEvents();QVERIFY2(timer.elapsed()<100,"Night-Light click blocked the GUI thread.");QVERIFY(!night->isVisible());QVERIFY(nightSpinner->isVisible());QVERIFY(!headerBusy->isVisible());QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-night-light-spinner-active.png")));QTRY_VERIFY_WITH_TIMEOUT(night->isVisible(),1000);QVERIFY(!nightSpinner->isVisible());QVERIFY(raw->nightDisabled);QCOMPARE(nightStatus->text(),L("system.on"));
    timer.restart();light->click();QCoreApplication::processEvents();QVERIFY2(timer.elapsed()<100,"Windows-mode click blocked the GUI thread.");QVERIFY(!light->isVisible());QVERIFY(lightSpinner->isVisible());QVERIFY(!headerBusy->isVisible());QTRY_VERIFY_WITH_TIMEOUT(light->isVisible(),1000);QVERIFY(!lightSpinner->isVisible());QVERIFY(raw->lightMode);QCOMPARE(lightStatus->text(),L("system.on"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-local-system-spinner.png")));controller.shutdown();
}

void E2ETests::nightLightTransitionKeepsPanelVisible(){
    QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();fake->systemDelayMs=300;ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("night-focus.ini"))));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();
    auto *night=panel.findChild<QAbstractButton*>(QStringLiteral("disable-night-light-switch"));auto *spinner=panel.findChild<QWidget*>(QStringLiteral("disable-night-light-spinner"));QVERIFY(night);QVERIFY(spinner);night->click();QVERIFY(!night->isVisible());QVERIFY(spinner->isVisible());
    QEvent windowDeactivated(QEvent::WindowDeactivate);QApplication::sendEvent(&panel,&windowDeactivated);QEvent appDeactivated(QEvent::ApplicationDeactivate);QApplication::sendEvent(qApp,&appDeactivated);QTest::qWait(100);QVERIFY2(panel.isVisible(),"Night Light's temporary Settings focus change hid the panel.");
    QTRY_VERIFY_WITH_TIMEOUT(night->isVisible(),1000);QVERIFY(panel.isVisible());QTest::qWait(80);
    QApplication::sendEvent(&panel,&windowDeactivated);QTRY_VERIFY2(!panel.isVisible(),"Normal focus-loss hiding did not resume after the Night Light operation.");controller.shutdown();
}

void E2ETests::buttonFocusFramesAreSuppressed(){
    QString baseStyle=QApplication::style()->objectName();if(baseStyle.isEmpty())baseStyle=QStringLiteral("windowsvista");ui::SmoothProxyStyle style(baseStyle);
    QPushButton button(QStringLiteral("Button"));button.resize(120,40);QStyleOptionFocusRect option;option.initFrom(&button);option.rect=button.rect();option.state|=QStyle::State_HasFocus;
    QImage image(button.size(),QImage::Format_ARGB32_Premultiplied);image.fill(Qt::transparent);QPainter painter(&image);style.drawPrimitive(QStyle::PE_FrameFocusRect,&option,&painter,&button);painter.end();
    for(int y=0;y<image.height();++y)for(int x=0;x<image.width();++x)QCOMPARE(qAlpha(image.pixel(x,y)),0);
}

